from math import hypot

def in_disk(p):
    return hypot(p[0], p[1]) <= 3            # a disk of radius 3

def in_ring(p):
    return 2 <= hypot(p[0], p[1]) <= 3       # a disk with a hole

def point_on_segment(x, y, lam):
    return (lam * x[0] + (1 - lam) * y[0], lam * x[1] + (1 - lam) * y[1])

