def grad_f(w1, w2):
    return (2 * (w1 - 3), 4 * (w2 - 1))

def check(point, budget, mu):
    g = point[0] + point[1] - budget             # the constraint g <= 0
    gf = grad_f(*point)
    stationarity = (gf[0] + mu * 1, gf[1] + mu * 1)     # grad f + mu * grad g, with grad g = (1, 1)
    return {
        "primal feasible (g <= 0)": g <= 1e-9,
        "dual feasible (mu >= 0)": mu >= 0,
        "complementary (mu * g = 0)": abs(mu * g) < 1e-9,
        "stationary": all(abs(s) < 1e-9 for s in stationarity),
    }

print(check((5 / 3, 1 / 3), 2, 8 / 3))   # case A: the constraint is active, mu = 8/3
print(check((3, 1), 6, 0))               # case B: the constraint is inactive, mu = 0

def solve(A, rhs):
    n = len(A)
    M = [A[i][:] + [rhs[i]] for i in range(n)]
    for c in range(n):
        p = max(range(c, n), key=lambda r: abs(M[r][c]))
        M[c], M[p] = M[p], M[c]
        for r in range(c + 1, n):
            f = M[r][c] / M[c][c]
            M[r] = [M[r][k] - f * M[c][k] for k in range(n + 1)]
    out = [0.0] * n
    for r in range(n - 1, -1, -1):
        out[r] = (M[r][n] - sum(M[r][k] * out[k] for k in range(r + 1, n))) / M[r][r]
    return out

def features(x, degree):
    z = x - 2.0
    return [z ** k for k in range(degree + 1)]

def fit_ridge(data, degree, lam):
    # minimizes MSE + lam * (sum of squared weights); the intercept (index 0) is not penalized
    X = [features(x, degree) for x, _ in data]
    n, p = len(X), degree + 1
    A = [[sum(row[i] * row[j] for row in X) + (lam * n if i == j and i > 0 else 0.0) for j in range(p)] for i in range(p)]
    rhs = [sum(row[i] * y for row, (_, y) in zip(X, data)) for i in range(p)]
    return solve(A, rhs)

def predict_poly(beta, x):
    return sum(c * f for c, f in zip(beta, features(x, len(beta) - 1)))

def mse(beta, data):
    return sum((predict_poly(beta, x) - y) ** 2 for x, y in data) / len(data)

